#!/usr/bin/env python3
"""Validate a team generated by agent-creator.

Usage:
    python validate_team.py <claude-dir> --team <root-slug>

<claude-dir> is the folder that holds agents/ and skills/: `.claude` inside a
project, or `~/.claude` for a global install.

Checks the agent files, the orchestrator skill, team.json and the knowledge
files they point to, prints the tree with models, and exits 1 on any error.
Existing agents the user chose to keep (origin "existing", action "keep") are
only checked for presence: they are the user's files, not ours.
Standard library only.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from collections import Counter
from pathlib import Path

MODEL_ALIASES = {"haiku", "sonnet", "opus", "fable", "inherit"}
EFFORTS = {"low", "medium", "high", "xhigh", "max"}
NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
MAX_DESCRIPTION = 300

# Agents are written in the user's language, so the two sections every leaf needs
# are matched in English and in its common translations (lowercase substrings).
SECTION_ALIASES = {
    "Output": (
        "output",
        "salida", "entrega", "resultado",          # es
        "sortie", "livrable",                       # fr
        "saída", "saida", "entregável",             # pt
        "ausgabe", "ergebnis",                      # de
        "uscita", "consegna", "risultato",          # it
    ),
    "Done when": (
        "done when", "definition of done", "done-when",
        "listo cuando", "está listo", "esta listo", "terminado cuando", "termina cuando",
        "definición de terminado", "criterio de terminado",                      # es
        "terminé quand", "termine quand", "fini quand", "fini lorsque",
        "définition de terminé",                                                 # fr
        "pronto quando", "concluído quando", "concluido quando", "feito quando", # pt
        "fertig wenn", "erledigt wenn", "definition of done",                    # de
        "finito quando", "completato quando", "fatto quando",                    # it
    ),
}


def parse_frontmatter(text: str) -> tuple[dict[str, str], str]:
    """Return (fields, body). Handles `key: value` and simple YAML lists."""
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 3)
    if end == -1:
        return {}, text
    block, body = text[3:end], text[end + 4 :]
    fields: dict[str, str] = {}
    key = None
    for line in block.splitlines():
        if not line.strip():
            continue
        if line.lstrip().startswith("- ") and key:
            fields[key] = (fields[key] + ", " + line.strip()[2:]).strip(", ")
            continue
        m = re.match(r"^([A-Za-z][\w-]*):\s*(.*)$", line)
        if m:
            key = m.group(1)
            fields[key] = m.group(2).strip().strip("'\"")
    return fields, body


def split_list(value: str) -> set[str]:
    value = value.strip("[]")
    return {v.strip().strip("'\"") for v in value.split(",") if v.strip()}


class Report:
    def __init__(self) -> None:
        self.errors: list[str] = []
        self.warnings: list[str] = []

    def error(self, where: str, msg: str) -> None:
        self.errors.append(f"ERROR   {where}: {msg}")

    def warn(self, where: str, msg: str) -> None:
        self.warnings.append(f"WARNING {where}: {msg}")


def check_agent(path: Path, report: Report, is_lead: bool, strict: bool = True) -> dict | None:
    fields, body = parse_frontmatter(path.read_text(encoding="utf-8"))
    where = path.name
    name = fields.get("name", "")
    model = fields.get("model", "") or "inherit"
    info = {"name": name or path.stem, "model": model, "effort": fields.get("effort") or "-",
            "lead": is_lead, "body": body, "path": path}
    if not fields:
        report.error(where, "no frontmatter (must start with ---)")
        return None
    if not name:
        report.error(where, "missing `name`")
    if not strict:
        return info  # an existing agent the user kept: presence is enough

    if name and not NAME_RE.match(name):
        report.error(where, f"name `{name}` must be lowercase letters, digits and dashes")
    elif name and name != path.stem:
        report.warn(where, f"name `{name}` differs from file name `{path.stem}`")

    desc = fields.get("description", "")
    if not desc:
        report.error(where, "missing `description` (the orchestrator routes by it)")
    elif len(desc) > MAX_DESCRIPTION:
        report.warn(where, f"description is {len(desc)} chars; keep it under {MAX_DESCRIPTION}")

    if not fields.get("model"):
        report.warn(where, "no `model`: it will inherit the caller's model, which defeats routing")
    elif model not in MODEL_ALIASES and not model.startswith("claude-"):
        report.error(where, f"unknown model `{model}`")

    effort = fields.get("effort", "")
    if effort and effort not in EFFORTS:
        report.error(where, f"unknown effort `{effort}`")

    tools = split_list(fields.get("tools", ""))
    disallowed = split_list(fields.get("disallowedTools", ""))
    if is_lead and tools and "Agent" not in tools:
        report.error(where, "lead agent needs `Agent` in tools to dispatch its leaves")
    if not is_lead:
        if "Agent" in tools:
            report.error(where, "leaf agent must not have `Agent` in tools")
        elif "Agent" not in disallowed:
            report.warn(where, "leaf agent should list `Agent` in disallowedTools")

    if "{{" in body or "{{" in desc:
        report.error(where, "unfilled template placeholder `{{...}}`")
    if len(body.strip()) < 200:
        report.warn(where, "body is very short; does it state input, output and done-when?")
    if not is_lead:
        low = body.lower()
        for section, aliases in SECTION_ALIASES.items():
            if not any(a in low for a in aliases):
                report.warn(where, f"no `{section}` section (or its translation)")
    return info


def find_agent_file(name: str, dirs: list[Path], explicit: str | None) -> Path | None:
    if explicit:
        p = Path(explicit).expanduser()
        return p if p.is_file() else None
    for d in dirs:
        if d.is_dir():
            hits = sorted(d.rglob(f"{name}.md"))
            if hits:
                return hits[0]
    return None


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("claude_dir", type=Path)
    ap.add_argument("--team", required=True, help="root slug, e.g. xix")
    args = ap.parse_args()
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")  # Windows consoles default to cp1252

    base: Path = args.claude_dir.expanduser()
    root = args.team
    report = Report()
    agents_dir = base / "agents"
    search_dirs = [agents_dir, Path.home() / ".claude" / "agents"]
    skill_dir = base / "skills" / root

    # team.json drives the check when present
    plan = None
    plan_path = skill_dir / "team.json"
    if plan_path.is_file():
        try:
            plan = json.loads(plan_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            report.error("team.json", f"invalid JSON: {e}")
    else:
        report.warn(str(plan_path), "missing; /agent-creator cannot update this team as a diff")

    agents: list[dict] = []
    branch_of: dict[str, str] = {}
    origin_of: dict[str, str] = {}
    seen_paths: set[Path] = set()

    if plan:
        for br in plan.get("branches", []):
            members = [(br["lead"], True)] if br.get("lead") else []
            members += [(leaf, False) for leaf in br.get("leaves", [])]
            for m, is_lead in members:
                origin = m.get("origin", "proposed")
                if origin == "existing" or m["name"].startswith(root + "-"):
                    full = m["name"]
                else:
                    full = f"{root}-{br['slug']}-{m['name']}"
                path = find_agent_file(full, search_dirs, m.get("file"))
                if not path:
                    report.error("team.json", f"`{full}` is planned but has no agent file")
                    continue
                keep = origin == "existing" and m.get("existing_action", "keep") == "keep"
                info = check_agent(path, report, is_lead or full.endswith("-lead"), strict=not keep)
                if info:
                    agents.append(info)
                    seen_paths.add(path.resolve())
                    branch_of[info["name"]] = br["slug"]
                    origin_of[info["name"]] = origin
                    if m.get("model") and not keep and m["model"] != info["model"]:
                        report.warn(full, f"model `{info['model']}` differs from team.json `{m['model']}`")
                    if origin == "existing" and m.get("existing_action") == "upgrade":
                        if not (skill_dir / "backup" / f"{full}.md").is_file():
                            report.warn(full, "upgraded agent has no backup in skills/<root>/backup/")

    # Agent files with the team prefix that the plan does not list
    if agents_dir.is_dir():
        for p in sorted(agents_dir.rglob(f"{root}-*.md")):
            if p.resolve() in seen_paths:
                continue
            info = check_agent(p, report, p.stem.endswith("-lead"))
            if info:
                agents.append(info)
                if plan:
                    report.warn(p.name, "agent file not listed in team.json")
    if not agents:
        report.error(str(agents_dir), f"no agents found for team `{root}`")

    names = Counter(a["name"] for a in agents)
    for n, c in names.items():
        if c > 1:
            report.error(n, f"name used by {c} files")

    # Orchestrator skill
    skill_md = skill_dir / "SKILL.md"
    if not skill_md.is_file():
        report.error(str(skill_md), "orchestrator skill missing")
    else:
        skill_text = skill_md.read_text(encoding="utf-8")
        fields, _ = parse_frontmatter(skill_text)
        if fields.get("name") != root:
            report.error("SKILL.md", f"`name` should be `{root}`")
        if not fields.get("description"):
            report.error("SKILL.md", "missing `description`")
        if "{{" in skill_text:
            report.error("SKILL.md", "unfilled template placeholder `{{...}}`")
        referenced = set(re.findall(rf"\b{re.escape(root)}-[a-z0-9-]+", skill_text))
        for ref in sorted(referenced - set(names)):
            report.error("SKILL.md", f"mentions `{ref}` but no such agent file exists")
        lead_bodies = " ".join(a["body"] for a in agents if a["lead"])
        for a in agents:
            if a["lead"]:
                continue
            if a["name"] not in skill_text and a["name"] not in lead_bodies:
                report.warn(a["name"], "not mentioned by the orchestrator or any lead; nothing will call it")

    # Knowledge files referenced from our agents' bodies
    for a in agents:
        if origin_of.get(a["name"]) == "existing" and a["path"].resolve() not in seen_paths:
            continue
        for ref in re.findall(r"`([^`]*knowledge[/\\][^`]+\.md)`", a["body"]):
            p = Path(ref).expanduser()
            if not p.is_absolute():
                p = skill_dir / "knowledge" / Path(ref).name
            if not p.is_file():
                report.error(a["name"], f"knowledge file not found: {ref}")

    # Tree
    print(f"\n{root}  (/{root})")
    tree: dict[str, list[dict]] = {}
    for a in agents:
        branch = branch_of.get(a["name"]) or a["name"][len(root) + 1 :].split("-")[0]
        tree.setdefault(branch, []).append(a)
    tags = {"existing": " (existing)", "user": " (added by user)", "suggested": " (suggested)"}
    for i, (branch, members) in enumerate(sorted(tree.items())):
        last_b = i == len(tree) - 1
        print(("└── " if last_b else "├── ") + branch)
        members.sort(key=lambda a: (not a["lead"], a["name"]))
        for j, a in enumerate(members):
            pre = "    " if last_b else "│   "
            mark = "└── " if j == len(members) - 1 else "├── "
            tag = tags.get(origin_of.get(a["name"], ""), "")
            print(f"{pre}{mark}{a['name']}  [{a['model']} · {a['effort']}]{tag}")

    tiers = Counter(a["model"] for a in agents)
    print("\nModels: " + ", ".join(f"{m} {n}" for m, n in tiers.most_common()))
    print(f"Agents: {len(agents)}\n")

    for line in report.warnings + report.errors:
        print(line)
    if report.errors:
        print(f"\n{len(report.errors)} error(s), {len(report.warnings)} warning(s).")
        return 1
    print(f"OK. {len(report.warnings)} warning(s).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
